 let mediaPending=false;
 const readAt=new Map();
 function escape(value){return String(value).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));}
 function alertPhone(text){alertText=text;$('#phoneAlert').textContent=text;$('#phoneAlert').hidden=!text;}
 function showPhone(){if(!dialog.open)dialog.showModal();renderPhone(true);}
