 function openApp(app){if(!['home',...KoraPhoneApps.apps.map(a=>a.id)].includes(app))return;view=app;thread=null;alertPhone('');renderPhone(true);}
 async function visitFromPhone(placeId,action){if(travelling){alertPhone('Finish your current journey first.');return;}if(!PLACES.some(p=>p.id===placeId))return;hidePhone();try{selected=placeId;if(state.location!==placeId){if(!await travel(placeId))return;}else render();if(action)runAction(action);}catch(e){toast('Could not reach that stop. Try selecting it on the city map.');}}
 async function furnishFromPhone(){if(travelling){alertPhone('Finish your current walk first.');return;}hidePhone();await window.openApartment();}
 const appContext={escape,openApp,notify:alertPhone,visit:visitFromPhone,furnish:furnishFromPhone};
 async function api(path,data){const response=await fetch('/api/'+path,{method:data===undefined?'GET':'POST',headers:data===undefined?{}:{'Content-Type':'application/json'},body:data===undefined?undefined:JSON.stringify(data),credentials:'same-origin',cache:'no-store',signal:AbortSignal.timeout(10000)});let json;try{json=await response.json();}catch(e){throw new Error('The phone server is not available at this game address.');}if(!response.ok){const error=new Error(json.error||'The phone could not connect.');error.status=response.status;throw error;}return json;}
